-- precision of the matched pairs, whole population not a sample: does the full first name agree, does the city agree (13 twins pooled + LESA alone)
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT DISTINCT LEFT(CONTRIBUTOR_ZIP,5)||IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z]+$'))
   ||LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) kk,
   REGEXP_SUBSTR(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),'[A-Z]+') fn,
   UPPER(TRIM(CONTRIBUTOR_CITY)) city
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g)
   AND NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|ITEMIZED|WITHHELD).*')),
f AS (SELECT DISTINCT CMTE_ID, LEFT(ZIP_CODE,5)||TRIM(SPLIT_PART(DONOR_NAME,',',1))||LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) kk,
   REGEXP_SUBSTR(TRIM(SPLIT_PART(UPPER(DONOR_NAME),',',2)),'[A-Z]+') fn, UPPER(TRIM(CITY)) city
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS WHERE COALESCE(MEMO_CD,'')<>'X'
   AND CMTE_ID IN ('C00570093','C00715433','C00709113','C00710160','C00650168','C00784496','C00755694','C00681825','C00570416','C00758938','C00712885','C00710178','C00699801')),
p AS (SELECT f.CMTE_ID, f.kk, MAX(IFF(s.fn=f.fn,1,0)) fn_ok, MAX(IFF(LEN(s.fn)>1 AND LEN(f.fn)>1 AND (STARTSWITH(s.fn,f.fn) OR STARTSWITH(f.fn,s.fn)),1,0)) fn_prefix, MAX(IFF(s.city=f.city,1,0)) city_ok,
   MAX(IFF(LEN(s.fn)<=1 OR LEN(f.fn)<=1,1,0)) initial_only
  FROM f JOIN s ON s.kk=f.kk GROUP BY 1,2)
SELECT IFF(CMTE_ID='C00681825','LESA','all 13') grp, COUNT(*) matched_pairs, ROUND(100*AVG(fn_ok),1) pct_same_first_name, ROUND(100*AVG(GREATEST(fn_ok,fn_prefix)),1) pct_first_name_or_prefix,
  ROUND(100*AVG(city_ok),1) pct_same_city, ROUND(100*AVG(IFF(fn_ok=0 AND fn_prefix=0 AND initial_only=0,1,0)),1) pct_first_name_conflict, ROUND(100*AVG(IFF(fn_ok=0 AND fn_prefix=0 AND initial_only=0 AND city_ok=0,1,0)),1) pct_conflict_and_diff_city
FROM p GROUP BY GROUPING SETS ((IFF(CMTE_ID='C00681825','LESA','all 13')), ())
